col1, col2 = st.columns([1, 1])

with col1:
    home_address = st.text_input(
        "Διεύθυνση κατοικίας σου",
        placeholder="π.χ. Πατησίων 100, Αθήνα",
    )

with col2:
    schools_raw = st.text_area(
        "Λίστα σχολείων (ένα σχολείο ανά γραμμή)",
        height=150,
        placeholder="32ο σχολείο Αθηνών\n2ο σχολείο Καισαριανής\n5ο σχολείο Νέας Φιλαδέλφειας",
    )

run = st.button("🔎 Βρες αποστάσεις & χάρτη", type="primary")

if run:
    if not home_address.strip():
        st.error("Συμπλήρωσε πρώτα τη διεύθυνση κατοικίας σου.")
        st.stop()
    if not schools_raw.strip():
        st.error("Επικόλλησε τη λίστα σχολείων.")
        st.stop()

    with st.spinner("Εντοπισμός διεύθυνσης κατοικίας..."):
        home_coords, geocode_errors = geocode_address(home_address)

    if not home_coords:
        st.error(
            "Δεν μπόρεσα να εντοπίσω αυτή τη διεύθυνση. Δοκίμασε πιο συγκεκριμένη μορφή "
            "(οδός, αριθμός, περιοχή)."
        )
        if geocode_errors:
            with st.expander("Τεχνικές λεπτομέρειες (για αν χρειαστεί υποστήριξη)"):
                for e in geocode_errors:
                    st.code(e)
        st.stop()

    st.success(f"Το σπίτι εντοπίστηκε στις συντεταγμένες: {home_coords}")

    raw_lines = [l for l in schools_raw.splitlines() if l.strip()]
    school_names = []
    for line in raw_lines:
        cleaned = clean_school_name(line)
        if cleaned and looks_like_school_line(cleaned):
            school_names.append(cleaned)
    school_names = list(dict.fromkeys(school_names))

    if not school_names:
        st.warning("Δεν αναγνωρίστηκε κανένα όνομα σχολείου στη λίστα.")
        st.stop()

    st.write(f"Βρέθηκαν **{len(school_names)}** πιθανά σχολεία. Αναζήτηση σε εξέλιξη...")
    progress = st.progress(0.0)
    status = st.empty()

    # ΣΗΜΑΝΤΙΚΟ: μόνο τα σχολεία που έγραψες παρακάτω θα εμφανιστούν στον χάρτη.
    results = []
    not_found = []
    for i, name in enumerate(school_names):
        status.write(f"Αναζήτηση: {name}")
        found = locate_school(name)
        if found:
            lat, lon, address, method, matched_name = found
            dist_km = geodesic(home_coords, (lat, lon)).km
            results.append({
                "Έγραψες": name,
                "Βρέθηκε ως": matched_name,
                "Απόσταση (χλμ)": round(dist_km, 2),
                "Διεύθυνση": address, "Πηγή": method,
                "_lat": lat, "_lon": lon,
            })
        else:
            not_found.append(name)
        progress.progress((i + 1) / len(school_names))
        time.sleep(0.2)

    status.empty()
    progress.empty()
    results.sort(key=lambda r: r["Απόσταση (χλμ)"])

    st.subheader("Αποτελέσματα (ταξινομημένα κατά απόσταση)")
    st.dataframe(
        [{k: v for k, v in r.items() if not k.startswith("_")} for r in results],
        use_container_width=True,
        hide_index=True,
    )

    if not_found:
        with st.expander(f"⚠ {len(not_found)} σχολεία δεν βρέθηκαν αυτόματα"):
            for n in not_found:
                st.write(f"- {n}")

    st.subheader("Διαδραστικός χάρτης")
    st.caption("Εμφανίζονται μόνο τα σχολεία της λίστας που επικόλλησες παραπάνω. Πάτα σε ένα σχολείο για δρομολόγιο από το σπίτι.")
    m = folium.Map(location=home_coords, zoom_start=12)
    folium.Marker(
        home_coords, popup="Το σπίτι μου", tooltip="Σπίτι",
        icon=folium.Icon(color="red", icon="home", prefix="fa"),
    ).add_to(m)
    for r in results:
        school_coords = (r["_lat"], r["_lon"])
        # Διακεκομμένη γραμμή σπίτι -> σχολείο (ευθεία, οπτική ένδειξη - όχι πραγματική διαδρομή)
        folium.PolyLine(
            [home_coords, school_coords],
            color="#4a90d9", weight=2, opacity=0.6, dash_array="6,6",
        ).add_to(m)

        home_lat, home_lon = home_coords
        sch_lat, sch_lon = school_coords

        # Για τα links του Google Maps προτιμάμε να στέλνουμε ΚΕΙΜΕΝΟ διεύθυνσης
        # αντί για lat/lon: το ίδιο το Google κάνει το δικό του (συνήθως πιο
        # ακριβές) geocoding, αντί να εμπιστευόμαστε τις δικές μας συντεταγμένες.
        origin_text = home_address.strip()
        if not re.search(r"ελλ[αά]δα|greece", origin_text, re.IGNORECASE):
            origin_text += ", Ελλάδα"
        origin_param = quote(origin_text)

        if r["Διεύθυνση"] and "Άγνωστη" not in r["Διεύθυνση"]:
            dest_param = quote(f"{r['Διεύθυνση']}, Ελλάδα")
        else:
            dest_param = f"{sch_lat},{sch_lon}"

        directions_driving = (
            f"https://www.google.com/maps/dir/?api=1&origin={origin_param}"
            f"&destination={dest_param}&travelmode=driving"
        )
        directions_walking = directions_driving.replace("travelmode=driving", "travelmode=walking")
        directions_transit = directions_driving.replace("travelmode=driving", "travelmode=transit")

        popup_html = f"""
        <div style="font-family: sans-serif; min-width: 220px;">
          <b>{r['Βρέθηκε ως']}</b><br>
          {r['Απόσταση (χλμ)']} χλμ από το σπίτι (ευθεία)<br>
          {r['Διεύθυνση']}<br><br>
          <a href="{directions_driving}" target="_blank">🚗 Οδηγίες (αυτοκίνητο)</a><br>
          <a href="{directions_walking}" target="_blank">🚶 Οδηγίες (περπάτημα)</a><br>
          <a href="{directions_transit}" target="_blank">🚌 Οδηγίες (Μ.Μ.Μ.)</a>
        </div>
        """
        folium.Marker(
            [r["_lat"], r["_lon"]],
            popup=folium.Popup(popup_html, max_width=280),
            tooltip=f"{r['Βρέθηκε ως']} ({r['Απόσταση (χλμ)']} χλμ) - πάτα για δρομολόγιο",
            icon=folium.Icon(color="blue", icon="graduation-cap", prefix="fa"),
        ).add_to(m)
    components.html(m._repr_html_(), height=520, scrolling=True)
else:
    st.info("Συμπλήρωσε τη διεύθυνση και τη λίστα σχολείων, μετά πάτα το κουμπί.")
